function bell_number(n){
    if (n === 0) return 1;

    // Build the Bell triangle
    let bell = [];
    bell[0] = [1];

    for (let i = 1; i <= n; i++) {
        bell[i] = [];
        bell[i][0] = bell[i - 1][i - 1];
        for (let j = 1; j <= i; j++) {
            bell[i][j] = bell[i][j - 1] + bell[i - 1][j - 1];
        }
    }

    return bell[n][0];
}
