function closest_num(N){
    let digits = N.toString().split('').map(Number);
    let n = digits.length;

    // Find the largest index i such that digits[i] > digits[i+1]
    let i = n - 2;
    while (i >= 0 && digits[i] <= digits[i + 1]) {
        i--;
    }

    if (i < 0) return -1;

    // Find the largest index j such that j > i and digits[j] < digits[i]
    let j = n - 1;
    while (digits[j] >= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    [digits[i], digits[j]] = [digits[j], digits[i]];

    // Reverse the suffix starting at digits[i+1] to get the largest possible suffix
    let left = i + 1, right = n - 1;
    while (left < right) {
        [digits[left], digits[right]] = [digits[right], digits[left]];
        left++;
        right--;
    }

    return parseInt(digits.join(''));
}
