```javascript
function encode(message){
    const vowels = 'aeiouAEIOU';
    let result = '';
    for (let i = 0; i < message.length; i++) {
        let c = message[i];
        if (c === ' ') {
            result += c;
        } else {
            let isVowel = vowels.includes(c);
            // Swap case
            if (c === c.toUpperCase()) {
                c = c.toLowerCase();
            } else {
                c = c.toUpperCase();
            }
            // If it was a vowel, shift 2 places ahead
            if (isVowel) {
                let base = c.toLowerCase();
                let shifted = String.fromCharCode(base.charCodeAt(0) + 2);
                if (c === c.toUpperCase()) {
                    c = shifted.toUpperCase();
                } else {
                    c = shifted.toLowerCase();
                }
            }
            result += c;
        }
    }
    return result;
}
