```javascript
function Find_Min(lst){
    if (lst.length === 0) return 0;

    const distinct = new Set(lst).size;

    let left = 0;
    let count = 0;
    let minLen = lst.length;
    const freq = new Map();

    for (let right = 0; right < lst.length; right++) {
        freq.set(lst[right], (freq.get(lst[right]) || 0) + 1);
        if (freq.get(lst[right]) === 1) {
            count++;
        }

        while (count === distinct) {
            minLen = Math.min(minLen, right - left + 1);
            freq.set(lst[left], freq.get(lst[left]) - 1);
            if (freq.get(lst[left]) === 0) {
                count--;
            }
            left++;
        }
    }

    return minLen;
}
```

