  if (array[0] > start) return start;

  let low = 0;
  let high = array.length - 1;

  while (low <= high) {
    let mid = Math.floor((low + high) / 2);

    if (array[mid] === mid + start) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return low + start;
}
