function maxAverageOfPath(cost) {
    if (!cost || cost.length === 0) {
        return 0;
    }

    const n = cost.length;
    const dp = new Array(n).fill(0);

    dp[0] = cost[0][0];

    for (let j = 1; j < n; j++) {
        dp[j] = dp[j - 1] + cost[0][j];
    }

    for (let i = 1; i < n; i++) {
        dp[0] += cost[i][0];

        for (let j = 1; j < n; j++) {
            dp[j] = Math.max(dp[j], dp[j - 1]) + cost[i][j];
        }
    }

    return dp[n - 1] / (2 * n - 1);
}
