function lcs_of_three(X, Y, Z){
    let m = X.length;
    let n = Y.length;
    let p = Z.length;

    // Create 3D DP table initialized to 0
    let L = [];
    for (let i = 0; i <= m; i++) {
        L[i] = [];
        for (let j = 0; j <= n; j++) {
            L[i][j] = [];
            for (let k = 0; k <= p; k++) {
                L[i][j][k] = 0;
            }
        }
    }

    for (let i = 1; i <= m; i++) {
        for (let j = 1; j <= n; j++) {
            for (let k = 1; k <= p; k++) {
                if (X[i - 1] === Y[j - 1] && Y[j - 1] === Z[k - 1]) {
                    L[i][j][k] = L[i - 1][j - 1][k - 1] + 1;
                } else {
                    L[i][j][k] = Math.max(L[i - 1][j][k], L[i][j - 1][k], L[i][j][k - 1]);
                }
            }
        }
    }

    return L[m][n][p];
}
