```javascript
function do_algebra(operator, operand) {
    const precedence = {
        '+': 1,
        '-': 1,
        '*': 2,
        '//': 2,
        '**': 3
    };

    const rightAssociative = {
        '**': true
    };

    const output = [];
    const stack = [];

    for (let i = 0; i < operand.length; i++) {
        output.push(operand[i]);

        if (i < operator.length) {
            const op = operator[i];

            while (
                stack.length > 0 &&
                (
                    precedence[stack[stack.length - 1]] > precedence[op] ||
                    (
                        precedence[stack[stack.length - 1]] === precedence[op] &&
                        !rightAssociative[op]
                    )
                )
            ) {
                output.push(stack.pop());
            }

            stack.push(op);
        }
    }

    while (stack.length > 0) {
        output.push(stack.pop());
    }

    const evalStack = [];

    for (const token of output) {
        if (typeof token === 'number') {
            evalStack.push(token);
        } else {
            const b = evalStack.pop();
            const a = evalStack.pop();

            switch (token) {
                case '+':
                    evalStack.push(a + b);
                    break;
                case '-':
                    evalStack.push(a - b);
                    break;
                case '*':
                    evalStack.push(a * b);
                    break;
                case '//':
                    evalStack.push(Math.floor(a / b));
                    break;
                case '**':
                    evalStack.push(Math.pow(a, b));
                    break;
            }
        }
    }

    return evalStack[0];
}
